<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Orders';$msg='';$err='';$allowed=['PENDING','CONFIRMED','PROCESSING','PACKED','DISPATCHED','OUT_FOR_DELIVERY','DELIVERED','CANCELLED'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['order_id'];$status=$_POST['status'];$notes=trim($_POST['notes']??'Management status update');$location=trim($_POST['tracking_location']??'');$eta=trim($_POST['tracking_eta']??'');if(in_array($status,$allowed,true)){try{$s=$pdo->prepare('SELECT status,customer_id,order_number,total_amount FROM orders WHERE order_id=?');$s->execute([$id]);$o=$s->fetch();$pdo->prepare('UPDATE orders SET status=?,tracking_location=?,tracking_eta=? WHERE order_id=?')->execute([$status,$location!==''?$location:null,$eta!==''?$eta:null,$id]);$pdo->prepare('INSERT INTO order_status_history(order_id,status,notes) VALUES(?,?,?)')->execute([$id,$status,$notes]); audit_log('UPDATE ORDER STATUS','order_id='.$id.' status='.$status);$pdo->prepare('INSERT INTO customer_messages(customer_id,subject,message) VALUES(?,?,?)')->execute([(int)$o['customer_id'],'Order '.$o['order_number'].' update','Your order is now '.order_status_label($status).'. '.($notes?:'We have updated your delivery status.')]);$emailSent=false;try{$cq=$pdo->prepare('SELECT email,full_name FROM customers WHERE customer_id=? LIMIT 1');$cq->execute([(int)$o['customer_id']]);$cc=$cq->fetch();if($cc&&filter_var($cc['email'],FILTER_VALIDATE_EMAIL)){$emailSent=send_order_email($cc['email'],$o['order_number'],$status,money((float)$o['total_amount']), '/customer/order.php?id='.$id);}}catch(Throwable $ignore){}$msg=$emailSent?'Order status updated and the customer was notified by web Inbox and email.':'Order status updated and the customer was notified in the web Inbox. Email delivery was unavailable.';}catch(Throwable $e){$err='The order update could not be saved.';}}}$rows=$pdo->query('SELECT o.*,c.full_name,c.email FROM orders o JOIN customers c ON c.customer_id=o.customer_id ORDER BY o.created_at DESC')->fetchAll();require __DIR__.'/../includes/header.php';?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/products.php">Products</a><a class="active" href="/admin/orders.php">Orders</a><a href="/admin/customers.php">Customers</a><a href="/admin/reviews.php">Reviews</a><?php if(super_admin()): ?><a href="/admin/users.php">Admin accounts</a><?php endif; ?><a href="/">View store</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">ORDER CONTROL</span><h1>Customer orders</h1><p>Status changes are written to the same history used by customer live tracking.</p></div></div><?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?><?php if($err): ?><div class="errors"><?=e($err)?></div><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Current status</th><th>Update & notify</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['order_number'])?></strong><small><?=e($r['created_at'])?></small></td><td><?=e($r['full_name'])?><small><?=e($r['email'])?></small></td><td><?=money((float)$r['total_amount'])?></td><td><span class="status-pill <?=e(order_status_class($r['status']))?>"><?=e(order_status_label($r['status']))?></span></td><td><form method="post" class="order-update-form"><?=csrf_field()?><input type="hidden" name="order_id" value="<?=$r['order_id']?>"><select name="status"><?php foreach($allowed as $st): ?><option <?=$st===$r['status']?'selected':''?>><?=$st?></option><?php endforeach; ?></select><input name="tracking_location" value="<?=e($r['tracking_location']??'')?>" placeholder="Current location/checkpoint"><input type="datetime-local" name="tracking_eta" value="<?=!empty($r['tracking_eta'])?e(date('Y-m-d\TH:i',strtotime($r['tracking_eta']))):''?>"><input name="notes" placeholder="Optional note to customer"><button class="btn small">Save & notify</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php'; ?>
